package fr.shikkanime.ktor.session

/**
 * Names of the HTTP headers carrying the session correlation identifiers.
 *
 * The session identifier is a correlation token, never an authentication credential: a service
 * must not authorize a request from it.
 */
object SessionHeaders {
    /** Long-lived identifier of a client session. */
    const val SESSION_ID = "X-Session-Id"

    /** Identifier of one request, generated by the service receiving it. */
    const val REQUEST_ID = "X-Request-Id"

    /** Identifier of the request that triggered an outgoing call, when there is one. */
    const val PARENT_REQUEST_ID = "X-Parent-Request-Id"
}
